SELECT
	item_id AS itemId,
	SUM(sales_count) AS sumSalesCount,
	SUM(fixed_amount_count) AS sumFixedAmountCount,
	SUM(settle_amount_count) AS sumSettleAmountCount
FROM datacube_goods_data
WHERE sales_count > 0
AND count_date >= #{f.dateStart}
AND count_date <= #{f.dateEnd}

	AND company_id = #{f.companyId}


	AND merchant_id = #{f.merchantIdOrNull}



		AND order_class = #{f.orderClassValue}


		AND order_class IS NULL




		AND act_id IN

			#{aid}



		AND act_id = 0


GROUP BY item_id
ORDER BY SUM(sales_count) DESC
